        QurantimeItem("بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ. قُلْ هُوَ اللهُ أَحَدٌ ، اَللّٰهُ الصَّمَدُ ، لَمْ يَلِدْ وَلَمْ يُوْلَدْ ، وَلَمْ يَكُنْ لَّهُ كُفُوًا أَحَدٌ.", "من قالها حين يصبح وحين يمسى كفته من كل شيء.", 3, "audio/azkar/qt_02.mp3"),
        QurantimeItem("بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ. قُلْ أَعُوْذُ بِرَبِّ الْفَلَقِ ، مِنْ شَرِّ مَا خَلَقَ ، وَمِنْ شَرِّ غَاسِقٍ إِذَا وَقَبَ ، وَمِنْ شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ، وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ.", "من قالها حين يصبح وحين يمسى كفته من كل شيء.", 3, "audio/azkar/qt_03.mp3"),
        QurantimeItem("بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ. قُلْ أَعُوْذُ بِرَبِّ النَّاسِ ، مَلِكِ النَّاسِ ، إِلٰهِ النَّاسِ ، مِنْ شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ، اَلَّذِيْ يُوَسْوِسُ فِي صُدُوْرِ النَّاسِ ، مِنَ الْجِنَّةِ وَالنَّاسِ.", "من قالها حين يصبح وحين يمسى كفته من كل شيء.", 3, "audio/azkar/qt_04.mp3"),
        QurantimeItem("أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ ، وَالْحَمْدُ لِلَّهِ ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ.", "سؤال خير الليلة، والتعوذ من شرها وعذاب القبر.", 1, "audio/azkar/qt_07.mp3"),
        QurantimeItem("اللَّهُمَّ بِكَ أَمْسَيْنَا وَبِكَ أَصْبَحْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوْتُ وَإِلَيْكَ الْمَصِيْرُ.", "تفويض الأمر لله عند المساء.", 1, "audio/azkar/qt_08.mp3"),
        QurantimeItem("اللَّهُمَّ أَنْتَ رَبِّيْ لَا إِلَهَ إِلَّا أَنْتَ ، خَلَقْتَنِيْ وَأَنَا عَبْدُكَ ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ ، أَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ ، أَبُوْءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوْءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوْبَ إِلَّا أَنْتَ.", "سيد الاستغفار؛ من قاله موقناً ومات دخل الجنة.", 1, "audio/azkar/qt_09.mp3"),
        QurantimeItem("اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ ، أَشْهَدُ أَنْ لَّا إِلَهَ إِلَّا أَنْتَ ، أَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِيْ ، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ ، وَأَنْ أَقْتَرِفَ عَلَىٰ نَفْسِيْ سُوْءًا أَوْ أَجُرَّهُ إِلَىٰ مُسْلِمٍ.", "الحفظ من شر النفس والشيطان وشركه.", 1, "audio/azkar/qt_10.mp3"),
        QurantimeItem("اللَّهُمَّ إِنِّيْ أَمْسَيْتُ أُشْهِدُكَ ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ وَمَلَائِكَتَكَ وَجَمِيْعَ خَلْقِكَ ، أَنَّكَ أَنْتَ اللهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيْكَ لَكَ ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُوْلُكَ.", "العتق من النار.", 4, "audio/azkar/qt_12.mp3"),
        QurantimeItem("اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ.", "الوقاية من الشرك الأصغر والأكبر.", 1, "audio/azkar/qt_13.mp3"),
        QurantimeItem("اللَّهُمَّ مَا أَمْسَى بِي مِنْ نِّعْمَةٍ أَوْ بِأَحَدٍ مِّنْ خَلْقِكَ ، فَمِنْكَ وَحْدَكَ لَا شَرِيْكَ لَكَ ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ.", "أداء شكر الليلة.", 1, "audio/azkar/qt_15.mp3"),
        QurantimeItem("اللَّهُمَّ عَافِنِيْ فِي بَدَنِيْ ، اللَّهُمَّ عَافِنِيْ فِي سَمْعِيْ ، اللَّهُمَّ عَافِنِيْ فِي بَصَرِيْ ، لَا إِلَهَ إِلَّا أَنْتَ ، اللَّهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لَا إِلَهَ إِلَّا أَنْتَ.", "سؤال العافية، والتعوذ من الكفر والفقر وعذاب القبر.", 3, "audio/azkar/qt_16.mp3"),
        QurantimeItem("اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ.", "تفريج الهموم، وقضاء الديون، والوقاية من العجز.", 1, "audio/azkar/qt_17.mp3"),
        QurantimeItem("حَسْبِيَ اللهُ لَا إِلَهَ إِلَّا هُوَ ، عَلَيْهِ تَوَكَّلْتُ ، وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ.", "كفاية هموم الدنيا والآخرة.", 7, "audio/azkar/qt_18.mp3"),
        QurantimeItem("اللَّهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ ، اللَّهُمَّ إِنِّيْ أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِيْنِيْ وَدُنْيَايَ وَأَهْلِي وَمَالِي ، اللَّهُمَّ اسْتُرْ عَوْرَاتِيْ وَآمِنْ رَوْعَاتِيْ ، اللَّهُمَّ احْفَظْنِيْ مِنْ بَيْنِ يَدَيَّ ، وَمِنْ خَلْفِي ، وَعَنْ يَّمِيْنِيْ ، وَعَنْ شِمَالِي ، وَمِنْ فَوْقِيْ ، وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ.", "الحفظ الشامل من جميع الجهات، وستر العورات.", 1, "audio/azkar/qt_19.mp3"),
        QurantimeItem("بِسْمِ اللهِ الَّذِيْ لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ ، وَهُوَ السَّمِيْعُ الْعَلِيمُ.", "حماية تامة؛ لا يضره شيء.", 3, "audio/azkar/qt_20.mp3"),
        QurantimeItem("أَعُوْذُ بِكَلِمَاتِ اللهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ.", "الحفظ من شر المخلوقات وذوات السموم.", 3, "audio/azkar/qt_21.mp3"),
        QurantimeItem("رَضِيْتُ بِاللهِ رَبًّا ، وَبِالْإِسْلَامِ دِيْنًا ، وَبِمُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَبِيًّا.", "حق على الله أن يرضيه يوم القيامة.", 3, "audio/azkar/qt_22.mp3"),
        QurantimeItem("يَا حَيُّ يَا قَيُّوْمُ ، بِرَحْمَتِكَ أَسْتَغِيْثُ ، أَصْلِحْ لِي شَأْنِيْ كُلَّهُ ، وَلَا تَكِلْنِيْ إِلَىٰ نَفْسِيْ طَرْفَةَ عَيْنٍ.", "إصلاح الشأن كله، وعدم الوكول للنفس.", 3, "audio/azkar/qt_23.mp3"),
        QurantimeItem("أَمْسَيْنَا عَلَى فِطْرَةِ الْإِسْلَامِ ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ ، وَعَلَى دِيْنِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيْمَ حَنِيْفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِيْنَ.", "ختم اليوم بالثبات على التوحيد والسنة.", 1, "audio/azkar/qt_26.mp3"),
        QurantimeItem("سُبْحَانَ اللهِ وَبِحَمْدِهِ.", "حط الخطايا وإن كانت كزبد البحر.", 100, "audio/azkar/qt_27.mp3"),
        QurantimeItem("لَا إِلَهَ إِلَّا اللهُ وَحْدَهُ لَا شَرِيْكَ لَهُ ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرٌ.", "حرز من الشيطان، ومغفرة، وأجر عتق رقاب.", 100, "audio/azkar/qt_28.mp3"),
        QurantimeItem("وَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: «مَنْ قَالَ: أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَيَّ الْقَيُّومَ وَأَتُوبُ إِلَيْهِ، غَفَرَ اللَّهُ لَهُ، وَإِنْ كَانَ فَرَّ مِنَ الزَّحْفِ».", "غفران الذنوب ولو كانت من الكبائر.", 1, "audio/azkar/qt_31.mp3"),
        QurantimeItem("اللَّهُمَّ صَلِّ وَسَلِّمْ وَبَارِكْ على نَبِيِّنَا مُحمَّد.", "إدراك شفاعة النبي ﷺ يوم القيامة.", 10, "audio/azkar/qt_33.mp3"),
    )
}
